module util {
    # Round `amount` to 2 decimal places (decimal rounding, ties away from zero).
    function money_round(amount: decimal) -> decimal
        using (round(amount, 2));

    # Round `amount` to `places` decimal places. `places` may be zero or
    # negative. Coexists with the 1-argument overload above.
    function money_round(amount: decimal, places: int64) -> decimal
        using (round(amount, places));

    # Sum of all supplied amounts, rounded to 2 decimal places.
    # Returns 0 when called with no arguments.
    function total_of(variadic amounts: decimal) -> decimal
        using (money_round(sum(array_unpack(amounts))));

    # Reduce `amount` by `pct` percent, round to 2 decimal places, then
    # floor the result at `floor_amount` when that optional value is present.
    function apply_discount(
        amount: decimal,
        pct: decimal,
        floor_amount: optional decimal,
    ) -> decimal
        using (
            with d := money_round(amount - amount * pct / <decimal>100)
            select (
                d if not exists floor_amount else
                (d if d >= floor_amount else floor_amount)
            )
        );

    # Increase `net` by `tax_pct` percent (passable only by name, defaults
    # to 0), rounded to 2 decimal places.
    function gross_with_tax(net: decimal, named only tax_pct: decimal = <decimal>0) -> decimal
        using (money_round(net + net * tax_pct / <decimal>100));

    # Split `total` into exactly `count` amounts that sum to `total` exactly.
    # The first `count - 1` amounts are `total / count` rounded to 2 decimal
    # places; the last amount absorbs the remainder. Empty set when
    # `count < 1`.
    function installments(total: decimal, count: int64) -> set of decimal
        using (
            for i in range_unpack(range(1, (count + 1) if count >= 0 else 1))
            union (
                money_round(total / count) if i < count else
                total - money_round(total / count) * (count - 1)
            )
        );
}

module billing {
    type Customer {
        required name: str {
            constraint exclusive;
        }
        required discount_pct: decimal {
            default := <decimal>0;
        }
    }

    type Invoice {
        required code: str {
            constraint exclusive;
        }
        required customer: Customer;
        required paid: bool {
            default := false;
        }
        minimum_charge: decimal;
        required installment_count: int64 {
            default := 1;
        }

        link lines := .<invoice[is LineItem];

        property subtotal := util::money_round(sum(.lines.line_total));

        property total_due := util::apply_discount(
            .subtotal,
            .customer.discount_pct,
            .minimum_charge,
        );
    }

    type LineItem {
        required invoice: Invoice;
        required description: str;
        required qty: int64;
        required unit_price: decimal {
            constraint expression on (util::money_round(__subject__) = __subject__) {
                errmessage := "unit_price must not have more than 2 decimal places";
            }
        }

        property line_total := util::money_round(.qty * .unit_price);
    }

    function customer_outstanding(customer_name: str) -> decimal
        using (
            util::money_round(sum(
                (select Invoice filter .customer.name = customer_name and not .paid).total_due
            ))
        );
}

module reports {
    alias UnpaidInvoice := (
        select billing::Invoice filter not .paid
    );

    alias CustomerBalance := billing::Customer {
        outstanding := util::money_round(sum(
            (select .<customer[is billing::Invoice] filter not .paid).total_due
        ))
    };

    alias InvoicePlan := billing::Invoice {
        plan := util::installments(.total_due, .installment_count)
    };
}

