cd /home/user/pricing && gel query "
select (insert billing::Customer { name := 'Acme', discount_pct := 10n });
"

cd /home/user/pricing && gel query "
select (insert billing::Invoice {
  code := 'INV-1',
  customer := (select billing::Customer filter .name = 'Acme'),
  minimum_charge := 50n,
  installment_count := 3,
});
"
gel query "
select (insert billing::LineItem {
  invoice := (select billing::Invoice filter .code = 'INV-1'),
  description := 'Widget',
  qty := 3,
  unit_price := 10.5n,
});
"
gel query "
select (insert billing::LineItem {
  invoice := (select billing::Invoice filter .code = 'INV-1'),
  description := 'Gadget',
  qty := 2,
  unit_price := 2.25n,
});
"

cd /home/user/pricing && gel query "
select billing::Invoice {
  code, subtotal, total_due, installment_count
} filter .code = 'INV-1';
"
gel query "select billing::customer_outstanding('Acme');"
gel query "select billing::customer_outstanding('NoSuchCustomer');"

cd /home/user/pricing && gel query "
select reports::UnpaidInvoice { code, subtotal, total_due };
"
gel query "
select reports::CustomerBalance { name, outstanding };
"
gel query "
select reports::InvoicePlan { code, plan };
"

